"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["10456"],{54996(e){e.exports=JSON.parse('{"id":7009,"title":"Fu\xdfball Fakten","description":"\u201EDu denkst, du kennst Borussia Dortmund? Dann halt dich fest \u2013 hier kommen 5 krasse Fakten \xfcber den BVB, die du garantiert noch nicht kanntest!\u201C\\n\\n Fakt 1 \u2013 BVB wurde in einer Kneipe gegr\xfcndet\\n\u201EDer BVB wurde 1909 von 18 jungen M\xe4nnern in einer Kneipe namens \'Zum Wildsch\xfctz\' gegr\xfcndet \u2013 aus Protest gegen den Pfarrer ihres Sportvereins. Rebellisch von Anfang an!\u201C\\n\\n Fakt 2 \u2013 Der Fast-Ruin 2005\\n\u201E2005 war Borussia Dortmund finanziell am Abgrund \u2013 der Verein war so pleite, dass sogar der Erzfeind Bayern M\xfcnchen dem BVB zwei Millionen Euro Kredit gab, um ihn zu retten. Kein Witz!\u201C\\n\\nFakt 3 \u2013 Gelbe Wand = Weltrekord\\n\u201EDie S\xfcdtrib\xfcne im Signal Iduna Park ist mit \xfcber 25.000 Stehpl\xe4tzen die gr\xf6\xdfte Stehplatztrib\xfcne Europas \u2013 besser bekannt als \u201ADie Gelbe Wand\u2018. G\xe4nsehaut garantiert!\u201C\\n\\n Fakt 4 \u2013 J\xfcngster Meistertrainer ever\\n\u201EJ\xfcrgen Klopp wurde 2011 mit nur 43 Jahren Meister \u2013 als einer der j\xfcngsten Trainer in der Bundesliga-Geschichte. Und das mit einer Mannschaft, die fast nur aus Talenten bestand!\u201C\\n\\nFakt 5 \u2013 BVB auf dem Aktienmarkt\\n\u201EBorussia Dortmund ist der einzige Bundesligist, der an der B\xf6rse gelistet ist. Du kannst dir also tats\xe4chlich ein St\xfcck BVB kaufen \u2013 als Aktie.\u201C\\n\\n\\n\xdcber welchen Verein willst du noch interessante Fakten Wissen? Schreibe deinen Lieblingsverein in die Kommentare!","owner":"huetttners05@gmail.com","upvotes":2,"downvotes":0,"upvoteDifference":2,"updatedAt":"2026-04-13T20:38:43.236Z"}')}}]);